PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    service_id TEXT NOT NULL,
    status TEXT DEFAULT 'pending',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, tracking_code TEXT, lat TEXT, lng TEXT, description TEXT, payment_status TEXT DEFAULT 'unpaid', cancellation_actor TEXT, cancellation_type TEXT, cancellation_reason TEXT, customer_id INTEGER, provider_id INTEGER, service_label TEXT, origin_province TEXT DEFAULT 'تهران', origin_city TEXT DEFAULT 'تهران', origin_district TEXT, origin_notes TEXT, origin_property_type TEXT DEFAULT 'residential', origin_lat REAL DEFAULT 35.7219, origin_lng REAL DEFAULT 51.3347, has_elevator INTEGER DEFAULT 1, floor_number INTEGER DEFAULT 1, needs_parts INTEGER DEFAULT 0, urgency TEXT DEFAULT 'normal', pricing_model TEXT DEFAULT 'fixed', scheduled_date TEXT DEFAULT 'امروز', scheduled_time TEXT DEFAULT 'فوری', estimate_avg INTEGER DEFAULT 1800000, final_price INTEGER, insurance_tier_id TEXT DEFAULT 'gold_300m', updated_at TEXT);
INSERT INTO "requests" ("id","name","phone","service_id","status","created_at","tracking_code","lat","lng","description","payment_status","cancellation_actor","cancellation_type","cancellation_reason","customer_id","provider_id","service_label","origin_province","origin_city","origin_district","origin_notes","origin_property_type","origin_lat","origin_lng","has_elevator","floor_number","needs_parts","urgency","pricing_model","scheduled_date","scheduled_time","estimate_avg","final_price","insurance_tier_id","updated_at") VALUES(1,'سیامک','09168959294','برقکاری','completed','2026-09-12 09:30:06',NULL,NULL,NULL,NULL,'unpaid',NULL,NULL,NULL,NULL,NULL,NULL,'تهران','تهران',NULL,NULL,'residential',35.7219,51.3347,1,1,0,'normal','fixed','امروز','فوری',1800000,NULL,'gold_300m',NULL);
