INSERT INTO "settings" ("key","value") VALUES('service_categories_custom','[{"id":"hvac","label":"سرمایش و گرمایش","labelEn":"HVAC & Climate","icon":"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M12 2v20M2 12h20M4.93 4.93l14.14 14.14M4.93 19.07 19.07 4.93M8 4l4 4 4-4M8 20l4-4 4 4M4 8l4 4-4 4M20 8l-4 4 4 4\"/></svg>","subtitle":"کولر آبی، پکیج، شوفاژ، آبگرمکن و کولر گازی","subtitleEn":"Water coolers, AC, heating packages & radiators","showInHeader":true,"headerOrder":1,"headerUrl":"/services/hvac","article":{"title":"راهنمای تخصصی و جامع سرمایش و گرمایش ساختمان در تهران | نصب، تعمیر و سرویس تخصصی بهدون","excerpt":"خدمات تخصصی سرمایش و گرمایش در کلیه مناطق تهران با ضمانت کتبی. تعمیر و سرویس پکیج، کولر آبی، رادیاتور شوفاژ، آبگرمکن و کولر گازی توسط تکنسین‌های مجرب بهدون با نرخ مصوب اتحادیه.","contentHtml":"\n        <!-- ================= COMPREHENSIVE SEO GUIDE (> 1200 WORDS) ================= -->\n        <article class=\"mt-12 pt-10 border-t border-slate-200 text-slate-700 leading-relaxed text-justify space-y-8\" dir=\"rtl\">\n            \n            <header class=\"text-center max-w-3xl mx-auto space-y-4 mb-10\">\n                <span class=\"inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-brand-50 text-brand-700 text-xs font-bold border border-brand-200\">\n                    <svg class=\"w-4 h-4 text-[#8B1C31]\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"></path></svg>\n                    دانشنامه و راهنمای تخصصی تأسیسات ساختمانی در تهران\n                </span>\n                <h2 class=\"text-2xl md:text-3xl font-black text-slate-800 leading-tight\">\n                    راهنمای جامع نگهداری، تعمیرات و بهینه‌سازی سیستم‌های سرمایش و گرمایش در تهران\n                </h2>\n                <p class=\"text-sm text-slate-500 leading-relaxed\">\n                    هر آنچه مالکان، مستاجران و مدیران ساختمان در خصوص بازدهی انرژی، عیب‌یابی، هزینه سرویس‌ها و انتخاب تکنسین مجرب در تهران باید بدانند.\n                </p>\n            </header>\n\n            <!-- Quick Action Alert Box -->\n            <div class=\"bg-gradient-to-r from-[#133458] to-[#1c4b7d] rounded-3xl p-6 md:p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6\">\n                <div class=\"space-y-2 text-center md:text-right\">\n                    <h3 class=\"text-xl font-bold\">نیاز به خدمات اورژانسی تأسیسات در تهران دارید؟</h3>\n                    <p class=\"text-xs md:text-sm text-blue-100 max-w-xl leading-relaxed\">\n                        تکنسین‌های بهدون در تمامی مناطق ۲۲ گانه تهران (شمال، غرب، شرق، مرکز و جنوب) مستقر بوده و کمتر از ۴۵ دقیقه پس از ثبت درخواست در محل حاضر می‌شوند.\n                    </p>\n                </div>\n                <div class=\"flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto shrink-0\">\n                    <button type=\"button\" onclick=\"openRequestModal(''سرمایش و گرمایش'')\" class=\"w-full sm:w-auto px-6 py-3 bg-[#8B1C31] hover:bg-[#701627] text-white text-xs md:text-sm font-black rounded-xl shadow-lg transition-all transform hover:scale-105 text-center\">\n                        ثبت فوری درخواست آنلاین\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"w-full sm:w-auto px-6 py-3 bg-white/10 hover:bg-white/20 text-white text-xs md:text-sm font-bold rounded-xl backdrop-blur-sm border border-white/20 transition-all text-center flex items-center justify-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-400\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n\n            <!-- SECTION 1: Overview -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    مقدمه: اهمیت استراتژیک سرویس دوره‌ای تجهیزات سرمایشی و گرمایشی\n                </h3>\n                <p>\n                    تجهیزات تهویه مطبوع، سرمایشی و حرارتی، بیش از ۴۰ درصد از کل انرژی مصرفی یک واحد مسکونی یا اداری در کلانشهر تهران را به خود اختصاص می‌دهند. با توجه به شرایط اقلیمی پایتخت، تابستان‌های داغ و خشک و زمستان‌های سرد و پرنوسان، سیستم‌های سرمایش و گرمایش تحت بار کاری مداوم و سنگین فعالیت می‌کنند. رسوب املاح کلسیمی آب تهران در لوله‌ها و مبدل‌ها، آلودگی و گرد و غبار انباشته شده روی پوشال‌ها و کوئل‌ها، و استهلاک قطعات متحرک مانند پمپ‌ها و الکتروموتورها، در صورت عدم سرویس به موقع، به سرعت راندمان سیستم را تا ۳۵ درصد کاهش داده و استهلاک زودهنگام و هزینه‌های گزاف تعویض دستگاه را به دنبال خواهد داشت.\n                </p>\n                <p>\n                    پلتفرم خدمات ساختمانی <a href=\"/\" class=\"text-brand-600 font-bold hover:underline\">بهدون</a> با بهره‌گیری از کادر تکنسین‌های آموزش‌دیده و مجرب، با هدف شفاف‌سازی هزینه‌ها و ارتقای کیفیت استانداردهای اجرایی تأسیسات در تهران، بستری مستقیم برای ثبت، ارزیابی و اعزام کارشناسان فراهم ساخته است. اگر نیاز به بررسی پیوسته لوله‌کشی و شیرآلات مرتبط دارید، می‌توانید به صفحه <a href=\"/services/plumbing\" class=\"text-brand-600 font-bold hover:underline\">خدمات لوله‌کشی آب و فاضلاب</a> ما نیز مراجعه فرمایید.\n                </p>\n            </section>\n\n            <!-- SECTION 2: Deep Dive into Services -->\n            <section class=\"space-y-6\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    بررسی تفصیلی ارکان چهارگانه خدمات سرمایش و گرمایش در بهدون\n                </h3>\n\n                <!-- Sub-block 1 -->\n                <div class=\"bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-3\">\n                    <h4 class=\"text-lg font-bold text-slate-800 text-brand-600\">۱. نصب، راه‌اندازی و نگهداری تخصصی کولر آبی</h4>\n                    <p class=\"text-sm leading-relaxed\">\n                        کولر آبی دستگاهی به ظاهر ساده اما از نظر فنی نیازمند هماهنگی دقیق میان مدارهای هیدرولیکی و الکتریکی است. در شروع فصل گرما، روشن کردن کولر آبی بدون شستشوی کفی و تعویض پوشال می‌تواند باعث سوختن موتور در اثر سفت بودن یاتاقان‌ها شود. تکنسین‌های بهدون در فرایند سرویس، با اندازه‌گیری لقی شفت توربین، روغن‌کاری گریس نسوز یاتاقان، تنظیم شناور ضدسرریز و بررسی سلامت کابل برق، حداکثر بازدهی سرمایشی را با کمترین مصرف آب و برق تضمین می‌کنند. همچنین در صورت نیاز به بررسی سیم‌کشی فیوز یا تعویض کلید کولر، خدمات از طریق واحد <a href=\"/services/electrical\" class=\"text-brand-600 font-bold hover:underline\">برقکاری ساختمان بهدون</a> در همان جلسه قابل تجمیع و انجام است.\n                    </p>\n                </div>\n\n                <!-- Sub-block 2 -->\n                <div class=\"bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-3\">\n                    <h4 class=\"text-lg font-bold text-slate-800 text-brand-600\">۲. تعمیر، رسوب‌زدایی و عیب‌یابی بردهای پکیج دیواری</h4>\n                    <p class=\"text-sm leading-relaxed\">\n                        پکیج‌های مدرن به علت راندمان بالا و استقلال هر واحد ساختمانی، محبوب‌ترین سیستم گرمایشی در تهران هستند. اما به دلیل رسوب کربنات کلسیم، مبدل‌های صفحه‌ای این دستگاه‌ها پس از ۱ تا ۲ سال دچار انسداد جزئی یا کامل می‌شوند. اسیدشویی ناصحیح توسط افراد ناوارد با اسیدهای خالص صنعتی موجب سوراخ شدن مبدل حرارتی گران‌قیمت می‌گردد. در بهدون، رسوب‌زدایی با اسیدهای محافظ‌دار دیسکلر گیاهی استاندارد و پمپ سیرکوله پرتابل انجام می‌گیرد. همچنین تست عیب‌یابی پمپ ویلو و گراندفوس، کالیبراسیون سنسور شعله و یون، و تنظیم گیج منبع انبساط با دستگاه فشارسنج دیجیتال صورت می‌پذیرد.\n                    </p>\n                </div>\n\n                <!-- Sub-block 3 -->\n                <div class=\"bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-3\">\n                    <h4 class=\"text-lg font-bold text-slate-800 text-brand-600\">۳. نصب و هواگیری رادیاتور و بهینه‌سازی راندمان شوفاژ</h4>\n                    <p class=\"text-sm leading-relaxed\">\n                        مشکل شایع گرم نشدن شوفاژها در زمستان، عمدتاً ناشی از تجمع هوا در پره‌های فوقانی و لجن سیاه‌رنگ ناشی از اکسیداسیون داخل لوله‌ها در پره‌های پایینی است. هواگیری غیراصولی می‌تواند به هرز شدن شیر هواگیری یا نشتی آب روی پارکت و فرش منجر شود. در صورت بروز هرگونه نم یا تخریب اطراف شوفاژ، تیم <a href=\"/services/renovation\" class=\"text-brand-600 font-bold hover:underline\">بازسازی و نقاشی ساختمان</a> در کنار تکنسین‌های تأسیسات آماده خدمت‌رسانی خواهند بود. متخصصان بهدون با شستشوی فشاری مدار و بالانس شیرهای برگشت، توزیع حرارت در دورترین رادیاتورها را یکنواخت می‌سازند.\n                    </p>\n                </div>\n\n                <!-- Sub-block 4 -->\n                <div class=\"bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-3\">\n                    <h4 class=\"text-lg font-bold text-slate-800 text-brand-600\">۴. تعمیرات، رفع افت فشار و سرویس آبگرمکن دیواری</h4>\n                    <p class=\"text-sm leading-relaxed\">\n                        نوسانات دمای آب در هنگام استحمام یا دیر روشن شدن آبگرمکن از شایع‌ترین مشکلات خانه‌ها است. علت این عارضه اغلب فرسودگی دیافراگم لاستیکی، رسوب در نازل شیپوره یا خرابی ترموکوپل و شمعک است. در بهدون کلیه قطعات یدکی مصرفی از جمله دیافراگم سیلیکونی مقاوم به حرارت و بوبین‌های ایمنی اصل با فاکتور معتبر و گارانتی تعویض می‌شوند.\n                    </p>\n                </div>\n            </section>\n\n            <!-- SECTION 3: Troubleshooting Table -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    جدول راهنمای عیب‌یابی سریع مشکلات سرمایش و گرمایش\n                </h3>\n                <p class=\"text-sm text-slate-600\">\n                    قبل از تماس با تکنسین، می‌توانید با بررسی جدول زیر علت احتمالی و اقدامات اولیه را بررسی کنید:\n                </p>\n\n                <div class=\"overflow-x-auto rounded-2xl border border-slate-200 shadow-sm bg-white\">\n                    <table class=\"w-full text-right text-xs md:text-sm\">\n                        <thead class=\"bg-slate-100/80 text-slate-800 font-bold border-b border-slate-200\">\n                            <tr>\n                                <th class=\"p-3.5 md:p-4\">نشانه و مشکل مشاهده‌شده</th>\n                                <th class=\"p-3.5 md:p-4\">علت فنی و ریشه‌ای</th>\n                                <th class=\"p-3.5 md:p-4\">اقدام پیشنهادی بهدون</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-slate-100 text-slate-600\">\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">باد کولر آبی خنک نیست اما موتور کار می‌کند</td>\n                                <td class=\"p-3.5 md:p-4\">خشک بودن پوشال‌ها، سوختن یا گرفتگی پمپ آب، پاره بودن تسمه</td>\n                                <td class=\"p-3.5 md:p-4\">سرویس پمپ و لوله‌های آبرسان، تنظیم یا تعویض تسمه</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">فشار پکیج مدام صفر می‌شود و افت می‌کند</td>\n                                <td class=\"p-3.5 md:p-4\">نشتی در اتصالات شوفاژ، خرابی شیر پرکن یا تخلیه باد منبع انبساط</td>\n                                <td class=\"p-3.5 md:p-4\">شارژ باد منبع انبساط، نشت‌یابی با دستگاه نقطه زن</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">آب مصرفی پکیج سرد و گرم می‌شود</td>\n                                <td class=\"p-3.5 md:p-4\">رسوب شدید در مبدل ثانویه، نقص در سنسور NTC آب گرم</td>\n                                <td class=\"p-3.5 md:p-4\">اسیدشویی تخصصی مبدل صفحه‌ای با دیسکلر استاندارد</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">شوفاژها در بالا گرم و در پایین کاملاً سرد هستند</td>\n                                <td class=\"p-3.5 md:p-4\">تجمع لجن و براده در مدار رادیاتور، ضعف دور گردش پمپ</td>\n                                <td class=\"p-3.5 md:p-4\">شستشوی پرفشار مدار رادیاتور و هواگیری تخصصی</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">شمعک آبگرمکن روشن نمی‌ماند</td>\n                                <td class=\"p-3.5 md:p-4\">خرابی ترموکوپل، سوختن بوبین ایمنی یا کثیفی نازل شمعک</td>\n                                <td class=\"p-3.5 md:p-4\">تمیزکاری پیلوت و تعویض قطعه ترموکوپل اورجینال</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </section>\n\n            <!-- SECTION 4: Why Behdoon -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    چرا پلتفرم بهدون انتخابی مطمئن برای خدمات سرمایش و گرمایش در تهران است؟\n                </h3>\n                <p>\n                    یافتن سرویس‌کار کاربلد و متعهد در کلانشهری مانند تهران همواره یکی از دغدغه‌های خانواده‌ها بوده است. بهدون با هدف ساماندهی این فضا، استانداردهای سخت‌گیرانه‌ای برای پذیرش و اعزام تکنسین تدوین نموده است:\n                </p>\n\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 pt-2\">\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2.5\">\n                        <div class=\"w-12 h-12 bg-emerald-100 text-emerald-700 rounded-2xl flex items-center justify-center mx-auto font-black text-lg\">\n                            ✓\n                        </div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">ضمانت کتبی کیفیت خدمات</h4>\n                        <p class=\"text-xs text-slate-500 leading-relaxed\">کلیه خدمات تعمیری و قطعات نصب‌شده دارای گارانتی رسمی بهدون بوده و در صورت بروز هرگونه ایراد در دوره ضمانت، رفع عیب کاملاً رایگان انجام می‌پذیرد.</p>\n                    </div>\n\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2.5\">\n                        <div class=\"w-12 h-12 bg-blue-100 text-blue-700 rounded-2xl flex items-center justify-center mx-auto font-black text-lg\">\n                            ⏱\n                        </div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">سرعت حضور در محل (زیر ۴۵ دقیقه)</h4>\n                        <p class=\"text-xs text-slate-500 leading-relaxed\">با توزیع شبکه‌ای تکنسین‌ها در شمال، غرب، شرق و مرکز تهران، کارشناس از نزدیک‌ترین ایستگاه خدماتی به آدرس ثبت شده شما اعزام می‌گردد.</p>\n                    </div>\n\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2.5\">\n                        <div class=\"w-12 h-12 bg-amber-100 text-amber-700 rounded-2xl flex items-center justify-center mx-auto font-black text-lg\">\n                            ⚖\n                        </div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">شفافیت نرخ و تعرفه مصوب</h4>\n                        <p class=\"text-xs text-slate-500 leading-relaxed\">هزینه‌ها دقیقاً منطبق بر نرخنامه مصوب اتحادیه تأسیسات مکانیکی و لوازم گازسوز تهران محاسبه شده و هیچ هزینه نامتعارفی دریافت نمی‌شود.</p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- SECTION 5: How it works & Tracking -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    فرایند ثبت و پیگیری هوشمند درخواست در بهدون\n                </h3>\n                <p>\n                    ما فرایند سفارش را به ساده‌ترین شکل ممکن طراحی کرده‌ایم تا در کمتر از ۱ دقیقه بتوانید درخواست خود را نهایی کنید:\n                </p>\n                <ol class=\"list-decimal list-inside space-y-2 text-sm text-slate-600 pr-2\">\n                    <li><strong>انتخاب خدمت:</strong> کلیک روی دکمه ثبت درخواست در بالای صفحه یا زیردسته‌های فوق و انتخاب نوع سرویس مورد نیاز.</li>\n                    <li><strong>تعیین موقعیت روی نقشه تهران:</strong> با کلیک روی نام محله خود یا جابجایی مارکر، لوکیشن دقیق خود را انتخاب می‌کنید.</li>\n                    <li><strong>تعیین زمان حضور:</strong> مشخص می‌کنید که کارشناس به صورت فوری اعزام شود یا در بازه زمانی خاصی از روزهای آتی مراجعه نماید.</li>\n                    <li><strong>دریافت آنی کد رهگیری:</strong> پس از ثبت شماره موبایل، سیستم یک کد پیگیری اختصاصی (مانند <code class=\"bg-slate-100 text-[#8B1C31] px-2 py-0.5 rounded font-mono font-bold\">BEH-XXXX</code>) صادر می‌کند که در صفحه <a href=\"/track\" class=\"text-brand-600 font-bold hover:underline\">پیگیری آنلاین درخواست‌ها</a> وضعیت اعزام تکنسین، ساعت ورود و گزارش کار را به طور لحظه‌ای به شما نمایش می‌دهد.</li>\n                </ol>\n            </section>\n\n            <!-- SECTION 6: Final CTA Banner -->\n            <div class=\"bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl p-6 md:p-8 text-center space-y-4 my-8\">\n                <h3 class=\"text-xl font-black text-slate-800\">آماده دریافت خدمات تخصصی سرمایش و گرمایش هستید؟</h3>\n                <p class=\"text-xs md:text-sm text-slate-600 max-w-xl mx-auto leading-relaxed\">\n                    هم‌اکنون درخواست خود را به صورت آنلاین ثبت نمایید تا نزدیک‌ترین تکنسین مجرب در منطقه شما با ابزار و قطعات استاندارد در محل حاضر شود.\n                </p>\n                <div class=\"flex flex-wrap items-center justify-center gap-3 pt-2\">\n                    <button type=\"button\" onclick=\"openRequestModal(''سرمایش و گرمایش'')\" class=\"bg-[#8B1C31] hover:bg-[#701627] text-white px-8 py-3.5 rounded-2xl font-black text-sm shadow-xl shadow-[#8B1C31]/25 hover:shadow-2xl transition-all transform hover:-translate-y-0.5\">\n                        ثبت فوری درخواست آنلاین (با کد رهگیری)\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"bg-white border border-slate-300 hover:bg-slate-100 text-slate-700 px-6 py-3.5 rounded-2xl font-bold text-sm shadow-sm transition-colors flex items-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-600\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>پشتیبانی تلفنی مستقیم: ۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n\n        </article>\n    ","metaTitle":"سرمایش و گرمایش در تهران | خدمات فوری و تضمینی بهدون","metaDescription":"خدمات تخصصی سرمایش و گرمایش در کلیه مناطق تهران با ضمانت کتبی. تعمیر و سرویس پکیج، کولر آبی، رادیاتور شوفاژ، آبگرمکن و کولر گازی توسط تکنسین‌های مجرب بهدون با نرخ مصوب اتحادیه.","readingTimeMinutes":5},"subServices":[{"id":"water-cooler","title":"نصب و سرویس کولر آبی","titleEn":"Water Cooler Service","basePrice":450000,"description":"سرویس کامل دوره‌ای، تعویض پوشال، تست و تعویض پمپ و دینام و روغن‌کاری یاتاقان‌ها","descriptionEn":"Professional service with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"package","title":"نصب و سرویس پکیج","titleEn":"Heating Package & Boiler","basePrice":650000,"description":"رسوب‌زدایی مبدل، رفع افت فشار، عیب‌یابی کدهای خطا، تعمیر برد الکترونیک و سرویس رادیاتور","descriptionEn":"Professional service with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"radiator","title":"نصب و سرویس رادیاتور شوفاژ","titleEn":"Radiator & Heating Valve","basePrice":400000,"description":"نصب و افزایش پره، رفع آب‌بندی و نشتی رادیاتور، تعویض شیر رفت‌وبرگشت و شیر ترموستاتیک","descriptionEn":"Professional service with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"water-heater","title":"تعمیر و سرویس آبگرمکن","titleEn":"Water Heater Service","basePrice":450000,"description":"جرم‌گیری کوئل مسی، تعویض دیافراگم، سرویس پیلوت، شمعک و کاربراتور آبگرمکن دیواری","descriptionEn":"Professional service with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"split-ac","title":"نصب و سرویس کولر گازی و اسپلیت","titleEn":"Split AC & Air Conditioning","basePrice":850000,"description":"شارژ گاز استاندارد R22 و R410، شستشوی پنل داخلی و کندانسور خارجی، نشت‌یابی و نصب","descriptionEn":"Professional service with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"}],"isCustom":false},{"id":"plumbing","label":"لوله‌کشی و تأسیسات","labelEn":"Plumbing & Pipes","icon":"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z\"/></svg>","subtitle":"نشت‌یابی نقطه زن، رفع نم، لوله بازکنی، شیرآلات، توالت و منبع آب","subtitleEn":"Acoustic leak detection, unclogging & pipe repairs","showInHeader":true,"headerOrder":2,"headerUrl":"/services/plumbing","article":{"title":"راهنمای تخصصی و جامع خدمات لوله‌کشی، نشت‌یابی و تأسیسات ساختمان در تهران | بهدون","excerpt":"خدمات تخصصی لوله‌کشی آب و فاضلاب، نشت‌یابی نقطه زن با دستگاه آکوستیک، رفع نم بدون تخریب، نصب شیرآلات، توالت فرنگی و منبع آب در تهران با ضمانت کتبی بهدون.","contentHtml":"\n        <!-- ================= COMPREHENSIVE PLUMBING SEO GUIDE (> 1300 WORDS) ================= -->\n        <article class=\"mt-12 pt-10 border-t border-slate-200 text-slate-700 leading-relaxed text-justify space-y-8\" dir=\"rtl\">\n            <header class=\"text-center max-w-3xl mx-auto space-y-4 mb-10\">\n                <span class=\"inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-cyan-50 text-cyan-800 text-xs font-bold border border-cyan-200\">\n                    <svg class=\"w-4 h-4 text-[#8B1C31]\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z\"></path></svg>\n                    دانشنامه تخصصی تأسیسات آبرسانی و فاضلاب ساختمان در تهران\n                </span>\n                <h2 class=\"text-2xl md:text-3xl font-black text-slate-800 leading-tight\">\n                    راهنمای جامع لوله‌کشی، تشخیص ترکیدگی لوله با دستگاه و رفع نم و رطوبت در تهران\n                </h2>\n                <p class=\"text-sm text-slate-500 leading-relaxed\">\n                    اصول مهندسی نشت‌یابی نقطه زن، رفع چکه و افت فشار آب ساختمان، نصب استاندارد تجهیزات بهداشتی و راه‌کارهای عایق‌بندی نانو بدون تخریب.\n                </p>\n            </header>\n\n            <!-- Quick Action Alert Box -->\n            <div class=\"bg-gradient-to-r from-[#0e2744] to-[#133458] rounded-3xl p-6 md:p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6\">\n                <div class=\"space-y-2 text-center md:text-right\">\n                    <h3 class=\"text-xl font-bold\">آب از سقف چکه می‌کند یا قبض آب شما ناگهان نجومی شده است؟</h3>\n                    <p class=\"text-xs md:text-sm text-cyan-100 max-w-xl leading-relaxed\">\n                        تکنسین‌های نشت‌یاب بهدون مجهز به پیشرفته‌ترین دستگاه‌های صوتی و تصویری نقطه زن در کمتر از ۴۵ دقیقه در محل حاضر شده و موضع دقیق ترکیدگی لوله را بدون تخریب نامتعارف مشخص می‌نمایند.\n                    </p>\n                </div>\n                <div class=\"flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto shrink-0\">\n                    <button type=\"button\" onclick=\"openRequestModal(''تشخیص و ترمیم ترکیدگی لوله'')\" class=\"w-full sm:w-auto px-6 py-3 bg-[#8B1C31] hover:bg-[#701627] text-white text-xs md:text-sm font-black rounded-xl shadow-lg transition-all transform hover:scale-105 text-center\">\n                        ثبت فوری درخواست نشت‌یابی\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"w-full sm:w-auto px-6 py-3 bg-white/10 hover:bg-white/20 text-white text-xs md:text-sm font-bold rounded-xl backdrop-blur-sm border border-white/20 transition-all text-center flex items-center justify-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-400\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n\n            <!-- SECTION 1: The challenge of plumbing in Tehran -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    چالش‌های لوله‌کشی و فرسودگی سیستم تأسیسات در بافت‌های مسکونی تهران\n                </h3>\n                <p>\n                    شبکه آبرسانی و لوله‌کشی در مناطق مختلف تهران به دلیل قدمت بناها، نوسانات شدید فشار آب شبکه در ساعات اوج مصرف، و حضور املاح خورنده آهکی در آب شرب، به صورت مداوم در معرض فرسودگی و آسیب‌های جدی است. در ساختمان‌های ساخته شده در دهه‌های ۷۰ و ۸۰ خورشیدی، استفاده از لوله‌های فولادی گالوانیزه و سیاه باعث خوردگی از داخل، زنگ‌زدگی، و سوراخ‌شدگی‌های تدریجی می‌گردد. از سوی دیگر، نشست‌های ساختمانی و ارتعاشات خیابانی تهران سبب گسستگی اتصالات در لوله‌های پی‌وی‌سی (پلیکا) و چدنی فاضلاب می‌شود.\n                </p>\n                <p>\n                    پلتفرم تخصصی <a href=\"/\" class=\"text-brand-600 font-bold hover:underline\">بهدون</a> با بهره‌گیری از تجهیزات مدرن آکوستیک، حرارتی و سیستم‌های لوله‌کشی پلیمری ۵ لایه، راهکارهای ماندگار و تضمین‌شده‌ای برای حل معضلات تأسیساتی همشهریان تهرانی ارائه می‌دهد. همچنین با هماهنگی کامل میان واحدهای <a href=\"/services/hvac\" class=\"text-brand-600 font-bold hover:underline\">سرویس پکیج و شوفاژ</a> و <a href=\"/services/renovation\" class=\"text-brand-600 font-bold hover:underline\">بنایی و کاشی‌کاری</a>، صفر تا صد عیب‌یابی، ترمیم لوله، و بازسازی کف و دیوار در کمترین زمان و با کمترین هزینه انجام می‌پذیرد.\n                </p>\n            </section>\n\n            <!-- SECTION 2: Detection Technology -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    فناوری نشت‌یابی نقطه زن تصویری: خداحافظی با تخریب‌های کورکورانه و پرهزینه\n                </h3>\n                <p>\n                    در گذشته نه چندان دور، هنگامی که لکه‌ای از نم روی سقف همسایه طبقه پایین پدیدار می‌شد، بناها اقدام به کندن کل کاشی‌های کف حمام و دستشویی می‌کردند تا منشأ نشتی را حدس بزنند! این فرآیند علاوه بر تحمیل میلیون‌ها تومان هزینه برای خرید مجدد کاشی، بنایی و ایزوگام، آرامش ساکنین را برای روزها برهم می‌زد.\n                </p>\n                <p>\n                    تکنسین‌های نشت‌یاب بهدون در تهران با استفاده از فناوری‌های ترکیبی ۳گانه:\n                </p>\n                <ul class=\"list-disc list-inside space-y-2 text-sm text-slate-600 pr-2\">\n                    <li><strong>دستگاه آکوستیک فوق‌حساس:</strong> فرکانس ریزترین ارتعاشات جریان خروج آب از درزها و سوراخ‌های میکروسکوپی لوله را تا عمق ۲ متر تقویت کرده و در هدفون کارشناس با وضوح بالا پخش می‌کند.</li>\n                    <li><strong>دوربین حرارتی مادون قرمز (ترموویژن):</strong> تغییرات دمایی سطح کف و دیوار را در اثر پخش شدن آب لوله‌های گرمایشی پکیج یا آب گرم مصرفی به صورت نقشه رنگی حرارتی نشان می‌دهد.</li>\n                    <li><strong>تست فشارسنج و گاز ردیاب هیدروژنی:</strong> برای خطوط لوله‌ای که نشتی بسیار نامحسوس دارند، با تزریق گاز بی‌خطر هیدروژن-نیتروژن و سنسور الکترونیکی بو، محل ترکیدگی در چند دقیقه کشف می‌شود.</li>\n                </ul>\n            </section>\n\n            <!-- SECTION 3: Troubleshooting table -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    جدول عیب‌یابی سریع نشانه‌های نشتی و مشکلات متداول لوله‌کشی در ساختمان\n                </h3>\n                <div class=\"overflow-x-auto rounded-2xl border border-slate-200 shadow-sm bg-white\">\n                    <table class=\"w-full text-right text-xs md:text-sm\">\n                        <thead class=\"bg-slate-100 text-slate-800 font-bold border-b border-slate-200\">\n                            <tr>\n                                <th class=\"p-3.5 md:p-4\">نشانه مشاهده‌شده</th>\n                                <th class=\"p-3.5 md:p-4\">علت احتمالی</th>\n                                <th class=\"p-3.5 md:p-4\">اقدام پیشنهادی بهدون</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-slate-100 text-slate-600\">\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">کنتور آب با وجود بسته بودن تمام شیرها می‌چرخد</td>\n                                <td class=\"p-3.5 md:p-4\">ترکیدگی لوله اصلی آب سرد زیر خاک حیاط یا کف واحد</td>\n                                <td class=\"p-3.5 md:p-4\">اعزام فوری نشت‌یاب با دستگاه صوتی دیجیتال</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">زردی، تبله گچ دیوار و شوره زدن سرامیک</td>\n                                <td class=\"p-3.5 md:p-4\">خرابی بندکشی کف حمام، نشت تدریجی از اتصالات لوله فاضلاب</td>\n                                <td class=\"p-3.5 md:p-4\">آب‌بندی نانو بدون تخریب یا اصلاح سیفون شترگلو</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">افت ناگهانی فشار آب در ساعات عصرگاهی طبقات ۳ به بالا</td>\n                                <td class=\"p-3.5 md:p-4\">نبود پمپ تحت فشار، رسوب در فیلترها، خرابی ست کنترل</td>\n                                <td class=\"p-3.5 md:p-4\">نصب پمپ آب خانگی و مخزن پلی‌اتیلن سه‌لایه</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">بوی زننده گاز فاضلاب در سرویس و آشپزخانه</td>\n                                <td class=\"p-3.5 md:p-4\">عدم وجود ونت هواکش فاضلاب، خشک شدن آب شترگلو، نشتی بوگیر توالت</td>\n                                <td class=\"p-3.5 md:p-4\">تعویض بوگیر ژله‌ای توالت فرنگی و نصب لوله ونت بام</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </section>\n\n            <!-- SECTION 4: Trust & Quality -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    مزایای رقابتی و استانداردهای خدمات لوله‌کشی بهدون در تهران\n                </h3>\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 pt-2\">\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-emerald-100 text-emerald-700 rounded-xl flex items-center justify-center mx-auto font-black\">✓</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">ضمانت کتبی عدم بازگشت نشتی</h4>\n                        <p class=\"text-xs text-slate-500\">کلیه خدمات نشت‌یابی و لوله‌کشی بهدون دارای ضمانت‌نامه رسمی و مهرشده هستند.</p>\n                    </div>\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-blue-100 text-blue-700 rounded-xl flex items-center justify-center mx-auto font-black\">⚡</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">اعزام شبانه‌روزی در کمتر از ۴۵ دقیقه</h4>\n                        <p class=\"text-xs text-slate-500\">تیم‌های امداد تأسیسات بهدون در شمال، شرق، غرب و مرکز تهران در حالت آماده‌باش هستند.</p>\n                    </div>\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-amber-100 text-amber-700 rounded-xl flex items-center justify-center mx-auto font-black\">⚖</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">محاسبه بر اساس نرخ مصوب اتحادیه</h4>\n                        <p class=\"text-xs text-slate-500\">هزینه‌ها کاملاً شفاف، منصفانه و طبق فاکتور رسمی اتحادیه تأسیسات مکانیکی تهران ارائه می‌گردد.</p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- SECTION 5: How to track and submit -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    نحوه ثبت سفارش آنلاین و دریافت کد رهگیری هوشمند\n                </h3>\n                <p>\n                    برای بهره‌مندی از خدمات لوله‌کشی و نشت‌یابی، کافیست روی دکمه‌های «ثبت آنلاین درخواست» کلیک کنید. در مرحله بعد موقعیت مکانی خود را روی نقشه تهران تعیین نمایید تا تکنسین کشیک منطقه شما مشخص شود. پس از تایید شماره موبایل، سیستم یک کد اختصاصی مانند <code class=\"bg-slate-100 text-[#8B1C31] px-2 py-0.5 rounded font-mono font-bold\">BEH-XXXX</code> صادر می‌کند که در صفحه <a href=\"/track\" class=\"text-brand-600 font-bold hover:underline\">پیگیری آنلاین درخواست‌ها</a> می‌توانید وضعیت اعزام و اطلاعات کارشناس را مشاهده نمایید.\n                </p>\n            </section>\n\n            <!-- Final CTA -->\n            <div class=\"bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl p-6 md:p-8 text-center space-y-4 my-8\">\n                <h3 class=\"text-xl font-black text-slate-800\">برای رفع مشکلات لوله‌کشی و نشت‌یابی ساختمان خود اقدام کنید</h3>\n                <p class=\"text-xs md:text-sm text-slate-600 max-w-xl mx-auto leading-relaxed\">\n                    هم‌اکنون درخواست خود را ثبت کنید تا در سریع‌ترین زمان ممکن از حضور کارشناسان مجرب بهدون با تجهیزات کامل در محل بهره‌مند شوید.\n                </p>\n                <div class=\"flex flex-wrap items-center justify-center gap-3 pt-2\">\n                    <button type=\"button\" onclick=\"openRequestModal(''لوله کشی آب و فاضلاب'')\" class=\"bg-[#8B1C31] hover:bg-[#701627] text-white px-8 py-3.5 rounded-2xl font-black text-sm shadow-xl shadow-[#8B1C31]/25 hover:shadow-2xl transition-all transform hover:-translate-y-0.5\">\n                        ثبت آنلاین درخواست خدمات لوله‌کشی\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"bg-white border border-slate-300 hover:bg-slate-100 text-slate-700 px-6 py-3.5 rounded-2xl font-bold text-sm shadow-sm transition-colors flex items-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-600\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>پشتیبانی شبانه‌روزی: ۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n        </article>\n    ","metaTitle":"لوله‌کشی و تأسیسات در تهران | خدمات فوری و تضمینی بهدون","metaDescription":"خدمات تخصصی لوله‌کشی آب و فاضلاب، نشت‌یابی نقطه زن با دستگاه آکوستیک، رفع نم بدون تخریب، نصب شیرآلات، توالت فرنگی و منبع آب در تهران با ضمانت کتبی بهدون.","readingTimeMinutes":5},"subServices":[{"id":"leak-detection","title":"تشخیص و ترمیم ترکیدگی لوله","titleEn":"Acoustic Pipe Leak Detection","basePrice":950000,"description":"نشت‌یابی نقطه زن با دستگاه آکوستیک و تصویری حرارتی پیشرفته بدون کمترین تخریب در ساختمان","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"moisture-repair","title":"رفع نم و نشتی و رطوبت","titleEn":"Damp & Moisture Repair","basePrice":850000,"description":"رفع نم و رطوبت دیوارها و سقف، عایق‌کاری پلیمری نانو بدون نیاز به تخریب کاشی و سرامیک","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"faucets","title":"نصب و تعمیر شیرآلات","titleEn":"Faucet & Tap Repair","basePrice":350000,"description":"نصب و تعمیر انواع شیرآلات اهرمی، توکار، چشمی، دوش حمام، سیفون، فلاش‌تانک و روشویی","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"water-tank","title":"نصب و سرویس منبع آب","titleEn":"Water Storage Tank & Pump","basePrice":800000,"description":"نصب مخازن پلی‌اتیلن سه‌لایه ضدجلبک، شناور برنجی، لوله‌کشی ورودی و خروجی و منبع ذخیره آب","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"toilet","title":"نصب و سرویس توالت فرنگی و ایرانی","titleEn":"Toilet Installation & Repair","basePrice":550000,"description":"نصب توالت فرنگی، تبدیل توالت ایرانی به فرنگی بدون کثیف‌کاری و رفع گرفتگی و بوگیری کاسه","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"piping","title":"لوله کشی آب و فاضلاب","titleEn":"Plumbing & Drainage Piping","basePrice":900000,"description":"لوله‌کشی آب سرد و گرم پنج‌لایه، نیوپایپ، پلی‌پروپیلن (سبز) و لوله‌کشی فاضلاب پوش‌فیت و پلیکا","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"sink","title":"نصب سینک ظرفشویی","titleEn":"Kitchen Sink & Trap","basePrice":400000,"description":"نصب انواع سینک توکار و روکار استیل و گرانیتی، آب‌بندی با چسب سیلیکون ضدقارچ و نصب سیفون","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"water-purifier","title":"نصب و تعمیر دستگاه تصفیه آب","titleEn":"Water Purifier Filter & Service","basePrice":450000,"description":"نصب و جابجایی دستگاه‌های تصفیه آب خانگی، تعویض دوره‌ای فیلترهای ۱ تا ۶ و تنظیم باد مخزن","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"flush-tank","title":"نصب و تعمیر فلاش تانک و سیفون","titleEn":"Flush Tank & Valve Repair","basePrice":350000,"description":"تعمیر و تنظیم مکانیزم تخلیه فلاش‌تانک، تعویض فلوتر، پمپ تخلیه و آب‌بندی لوله‌های رابط","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"washbasin","title":"نصب روشویی","titleEn":"Washbasin & Vanity Mounting","basePrice":450000,"description":"نصب انواع روشویی سنگی، کابینتی، پایه‌دار، آینه باکس، شیر مخلوط و آب‌بندی اتصالات","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"wall-hung","title":"نصب و تعمیر وال هنگ","titleEn":"Wall-Hung Concealed Toilet","basePrice":750000,"description":"نصب و سرویس استراکچر وال‌هنگ توکار، کلید تخلیه دو زمانه و رفع نشتی کاسه معلق","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"sewage-connection","title":"اتصال به شبکه فاضلاب شهری","titleEn":"City Sewage Network Connection","basePrice":1200000,"description":"حفر کانال، لوله‌گذاری اصولی شیب‌دار و اتصال استاندارد به شبکه اگو شهری با مجوز","descriptionEn":"Professional plumbing services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"}],"isCustom":false},{"id":"electrical","label":"برقکاری ساختمان","labelEn":"Electrical Works","icon":"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg>","subtitle":"رفع اتصالی فوری، سیم‌کشی، لوستر، کلید و پریز، آیفون، تابلو برق و دوربین","subtitleEn":"Short-circuit fix, wiring, fixtures & outlets","showInHeader":true,"headerOrder":3,"headerUrl":"/services/electrical","article":{"title":"راهنمای تخصصی و جامع خدمات برقکاری ساختمان در تهران | رفع اتصالی، سیم‌کشی و روشنایی فوری بهدون","excerpt":"خدمات تخصصی برق‌کاری ساختمان، عیب‌یابی و رفع فوری اتصالی شبانه‌روزی، سیم‌کشی کلی و جزئی، نصب لوستر، کلید و پریز، آیفون و تابلو برق در کلیه مناطق تهران.","contentHtml":"\n        <!-- ================= COMPREHENSIVE ELECTRICAL SEO GUIDE (> 1300 WORDS) ================= -->\n        <article class=\"mt-12 pt-10 border-t border-slate-200 text-slate-700 leading-relaxed text-justify space-y-8\" dir=\"rtl\">\n            <header class=\"text-center max-w-3xl mx-auto space-y-4 mb-10\">\n                <span class=\"inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-amber-50 text-amber-800 text-xs font-bold border border-amber-200\">\n                    <svg class=\"w-4 h-4 text-[#8B1C31]\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 10V3L4 14h7v7l9-11h-7z\"></path></svg>\n                    دانشنامه تخصصی تأسیسات الکتریکی و برقکاری ساختمان در تهران\n                </span>\n                <h2 class=\"text-2xl md:text-3xl font-black text-slate-800 leading-tight\">\n                    راهنمای جامع برقکاری ساختمان، رفع اتصالی، سیم‌کشی اصولی و سیستم‌های ایمنی در تهران\n                </h2>\n                <p class=\"text-sm text-slate-500 leading-relaxed\">\n                    اصول پیشگیری از اتصالی، استانداردهای کابل‌کشی، انتخاب کلید و پریز، نصب ایمن روشنایی و نقش حیاتی سیستم چاه ارت در حفاظت از ساکنان.\n                </p>\n            </header>\n\n            <!-- Quick Action Alert Box -->\n            <div class=\"bg-gradient-to-r from-[#1c2e42] to-[#263e59] rounded-3xl p-6 md:p-8 text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6\">\n                <div class=\"space-y-2 text-center md:text-right\">\n                    <h3 class=\"text-xl font-bold\">برق منزلتان قطع شده یا بوی سوختگی از جعبه فیوز احساس می‌کنید؟</h3>\n                    <p class=\"text-xs md:text-sm text-amber-100 max-w-xl leading-relaxed\">\n                        اتصالی برق می‌تواند در چند ثانیه به آتش‌سوزی گسترده منجر شود! امداد برقکاران شبانه‌روزی بهدون در سراسر مناطق ۲۲ گانه تهران آماده اعزام فوری هستند.\n                    </p>\n                </div>\n                <div class=\"flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto shrink-0\">\n                    <button type=\"button\" onclick=\"openRequestModal(''رفع اتصالی'')\" class=\"w-full sm:w-auto px-6 py-3 bg-[#8B1C31] hover:bg-[#701627] text-white text-xs md:text-sm font-black rounded-xl shadow-lg transition-all transform hover:scale-105 text-center\">\n                        اعزام فوری برقکار\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"w-full sm:w-auto px-6 py-3 bg-white/10 hover:bg-white/20 text-white text-xs md:text-sm font-bold rounded-xl backdrop-blur-sm border border-white/20 transition-all text-center flex items-center justify-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-400\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n\n            <!-- SECTION 1: Electrical safety -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    اهمیت حیاتی ایمنی الکتریکی و استانداردهای سیم‌کشی ساختمان در تهران\n                </h3>\n                <p>\n                    طبق گزارش‌های رسمی سازمان آتش‌نشانی و خدمات ایمنی تهران، بیش از ۳۵ درصد از حریق‌های منازل مسکونی و واحدهای تجاری ناشی از عیوب اتصالات برقی، فرسودگی عایق کابل‌ها و اضافه‌بار بر روی سیم‌کشی‌های غیراستاندارد است. در سال‌های اخیر با اضافه شدن تجهیزات پرمصرف نظیر ماشین ظرفشویی، ماکروویو، پکیج، کولرهای گازی اسپلیت و پمپ‌های تحت فشار آب، سیستم‌های سیم‌کشی قدیمی ساختمان‌ها با آمپراژ نامتناسب دچار داغ‌شدگی و آتش‌سوزی در داکت‌ها و پشت پریزها می‌شوند.\n                </p>\n                <p>\n                    واحد تأسیسات الکتریکی <a href=\"/\" class=\"text-brand-600 font-bold hover:underline\">بهدون</a> با بهره‌گیری از تکنسین‌های دارای گواهینامه معتبر فنی و مهندسی، ضمن رعایت دقیق مقررات ملی ساختمان (مبحث ۱۳)، کلیه امور طراحی، ارتقای کابل‌کشی، نصب تجهیزات حفاظتی و عیب‌یابی برق را با بالاترین استانداردهای ایمنی به انجام می‌رساند. همچنین در صورت نیاز به سیم‌کشی پمپ آب یا سیستم‌های سرمایشی، این فرآیند با همکاری مستقیم تیم <a href=\"/services/plumbing\" class=\"text-brand-600 font-bold hover:underline\">لوله‌کشی و منبع آب</a> و <a href=\"/services/hvac\" class=\"text-brand-600 font-bold hover:underline\">سرویس کولر و پکیج</a> بدون فوت وقت پیاده‌سازی می‌گردد.\n                </p>\n            </section>\n\n            <!-- SECTION 2: Common electrical issues -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    جدول عیب‌یابی سریع مشکلات شایع برقی ساختمان و اقدامات اضطراری\n                </h3>\n                <div class=\"overflow-x-auto rounded-2xl border border-slate-200 shadow-sm bg-white\">\n                    <table class=\"w-full text-right text-xs md:text-sm\">\n                        <thead class=\"bg-slate-100 text-slate-800 font-bold border-b border-slate-200\">\n                            <tr>\n                                <th class=\"p-3.5 md:p-4\">نشانه مشاهده‌شده</th>\n                                <th class=\"p-3.5 md:p-4\">علت احتمالی</th>\n                                <th class=\"p-3.5 md:p-4\">اقدام پیشنهادی بهدون</th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"divide-y divide-slate-100 text-slate-600\">\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">فیوز اصلی با روشن شدن یک وسیله برقی قطع می‌شود</td>\n                                <td class=\"p-3.5 md:p-4\">اضافه بار مصرفی، ضعیف بودن آمپراژ فیوز مینیاتوری</td>\n                                <td class=\"p-3.5 md:p-4\">تقسیم بار خطوط و ارتقای فیوز به رنج متناسب استاندارد</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">بدنه فلزی لوازم برقی یا شیرآلات برق‌دار است</td>\n                                <td class=\"p-3.5 md:p-4\">عدم وجود سیستم ارتینگ، نشت فاز به اسکلت یا لوله‌ها</td>\n                                <td class=\"p-3.5 md:p-4\">اجرای کابل هم‌بندی ارت و نصب کلید محافظ جان (RCD)</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">چشمک زدن لامپ‌های ال‌ای‌دی در حالت خاموش بودن کلید</td>\n                                <td class=\"p-3.5 md:p-4\">جابجا بسته شدن فاز و نول در کلید یا القای ولتاژ نول</td>\n                                <td class=\"p-3.5 md:p-4\">اصلاح سرسیم‌بندی قوطی کلید و قرار دادن فاز در مسیر قطع</td>\n                            </tr>\n                            <tr class=\"hover:bg-slate-50/50\">\n                                <td class=\"p-3.5 md:p-4 font-bold text-slate-800\">تصویر آیفون تصویری پرش دارد یا آبی می‌شود</td>\n                                <td class=\"p-3.5 md:p-4\">سوختن برد تغذیه، پارگی کابل تصویر یا عدم استفاده از فویل</td>\n                                <td class=\"p-3.5 md:p-4\">تعمیر منبع تغذیه و تست خطوط کوپلر با تستر شبکه</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </section>\n\n            <!-- SECTION 3: Why Choose Behdoon -->\n            <section class=\"space-y-4\">\n                <h3 class=\"text-xl font-black text-slate-800 flex items-center gap-2 border-r-4 border-[#8B1C31] pr-3\">\n                    چرا خدمات برقکاری ساختمان بهدون در تهران متمایز است؟\n                </h3>\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 pt-2\">\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-emerald-100 text-emerald-700 rounded-xl flex items-center justify-center mx-auto font-black\">✓</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">تکنسین‌های تایید صلاحیت‌شده</h4>\n                        <p class=\"text-xs text-slate-500\">تمامی برقکاران بهدون دارای گواهینامه معتبر فنی و حرفه‌ای و تاییدیه عدم سوءپیشینه هستند.</p>\n                    </div>\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-blue-100 text-blue-700 rounded-xl flex items-center justify-center mx-auto font-black\">⚡</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">سرعت اعزام اورژانسی شبانه‌روزی</h4>\n                        <p class=\"text-xs text-slate-500\">پوشش کامل تمام مناطق تهران با تجهیزات تست مدار و قطعات یدکی استاندارد در کمتر از ۴۵ دقیقه.</p>\n                    </div>\n                    <div class=\"bg-slate-50 border border-slate-200 rounded-2xl p-5 text-center space-y-2\">\n                        <div class=\"w-10 h-10 bg-amber-100 text-amber-700 rounded-xl flex items-center justify-center mx-auto font-black\">⚖</div>\n                        <h4 class=\"font-bold text-slate-800 text-sm\">نرخ شفاف مصوب اتحادیه الکتریک</h4>\n                        <p class=\"text-xs text-slate-500\">ارائه فاکتور رسمی بدون دریافت هزینه‌های متفرقه یا پیش‌بینی‌نشده قبل از شروع کار.</p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- Final CTA -->\n            <div class=\"bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl p-6 md:p-8 text-center space-y-4 my-8\">\n                <h3 class=\"text-xl font-black text-slate-800\">برای سیم‌کشی، رفع اتصالی و روشنایی ساختمان خود نیاز به کارشناس دارید؟</h3>\n                <p class=\"text-xs md:text-sm text-slate-600 max-w-xl mx-auto leading-relaxed\">\n                    هم‌اکنون درخواست خود را به صورت آنلاین ثبت کنید تا کد پیگیری آنی دریافت کرده و وضعیت اعزام تکنسین را به صورت زنده مشاهده فرمایید.\n                </p>\n                <div class=\"flex flex-wrap items-center justify-center gap-3 pt-2\">\n                    <button type=\"button\" onclick=\"openRequestModal(''رفع اتصالی'')\" class=\"bg-[#8B1C31] hover:bg-[#701627] text-white px-8 py-3.5 rounded-2xl font-black text-sm shadow-xl shadow-[#8B1C31]/25 hover:shadow-2xl transition-all transform hover:-translate-y-0.5\">\n                        ثبت آنلاین درخواست برقکار در تهران\n                    </button>\n                    <a href=\"tel:09333256885\" class=\"bg-white border border-slate-300 hover:bg-slate-100 text-slate-700 px-6 py-3.5 rounded-2xl font-bold text-sm shadow-sm transition-colors flex items-center gap-2\">\n                        <svg class=\"w-4 h-4 text-emerald-600\" fill=\"currentColor\" viewBox=\"0 0 512 512\"><path d=\"M164.9 24.6c-7.7-18.6-28-28.5-47.4-23.2l-88 24C12.1 30.2 0 46 0 64C0 311.4 200.6 512 448 512c18 0 33.8-12.1 38.6-29.5l24-88c5.3-19.4-4.6-39.7-23.2-47.4l-96-40c-16.3-6.8-35.2-2.1-46.3 11.6L304.7 368C234.3 334.7 177.3 277.7 144 207.3L193.3 167c13.7-11.2 18.4-30 11.6-46.3l-40-96z\"/></svg>\n                        <span>امداد برق تهران: ۰۹۳۳۳۲۵۶۸۸۵</span>\n                    </a>\n                </div>\n            </div>\n        </article>\n    ","metaTitle":"برقکاری ساختمان در تهران | خدمات فوری و تضمینی بهدون","metaDescription":"خدمات تخصصی برق‌کاری ساختمان، عیب‌یابی و رفع فوری اتصالی شبانه‌روزی، سیم‌کشی کلی و جزئی، نصب لوستر، کلید و پریز، آیفون و تابلو برق در کلیه مناطق تهران.","readingTimeMinutes":5},"subServices":[{"id":"short-circuit","title":"رفع اتصالی","titleEn":"Urgent Short-Circuit Troubleshooting","basePrice":550000,"description":"اعزام فوری برقکار برای عیب‌یابی اتصالی سیم‌کشی، رفع پریدن کنتور، فیوز مینیاتوری و برق‌دار بودن بدنه","descriptionEn":"Professional electrical services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"wiring","title":"سیم کشی و کابل کشی","titleEn":"Building Electrical Wiring","basePrice":700000,"description":"سیم‌کشی و کابل‌کشی کلی و جزئی مسکونی و تجاری، داکت‌کشی، خطوط تلفن و کابل شبکه","descriptionEn":"Professional electrical services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"chandelier","title":"نصب لوستر و چراغ","titleEn":"Chandelier & Lighting Installation","basePrice":450000,"description":"نصب مطمئن و مهار سنگین انواع لوسترهای سقفی، کریستالی، مدرن، چراغ‌های خطی و هالوژن","descriptionEn":"Professional electrical services with 30-day warranty in Tehran","guaranteeDays":30,"estimatedTime":"۳۰ الی ۶۰ دقیقه"},{"id":"switches","title":"کلید و پریز","titleEn":"Switches & Sockets Replacement","basePrice":300000,"description":"تعویض کلید و پریزهای قدیمی با مدل‌های مدرن لمسی و ارت‌د