CREATE TABLE job_applications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        full_name TEXT NOT NULL,
        phone TEXT NOT NULL,
        position TEXT,
        position_label TEXT,
        city TEXT,
        message TEXT,
        has_vehicle INTEGER,
        vehicle_type TEXT,
        status TEXT DEFAULT 'new',
        created_at TEXT
      );
