CREATE TABLE request_candidates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        provider_id INTEGER NOT NULL,
        matching_score REAL NOT NULL,
        rank INTEGER DEFAULT 1,
        selection_mode TEXT DEFAULT 'auto',
        status TEXT DEFAULT 'candidate',
        created_at TEXT NOT NULL
      , matching_breakdown TEXT);
CREATE TABLE quotes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        provider_id INTEGER NOT NULL,
        pricing_model TEXT NOT NULL DEFAULT 'fixed',
        base_amount INTEGER NOT NULL DEFAULT 0,
        materials_amount INTEGER NOT NULL DEFAULT 0,
        labor_amount INTEGER NOT NULL DEFAULT 0,
        discount_amount INTEGER NOT NULL DEFAULT 0,
        final_amount INTEGER NOT NULL,
        description TEXT,
        valid_until TEXT,
        status TEXT DEFAULT 'sent',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
CREATE TABLE provider_schedules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        provider_id INTEGER NOT NULL,
        date TEXT NOT NULL,
        time_slot TEXT NOT NULL,
        request_id INTEGER,
        status TEXT DEFAULT 'booked',
        created_at TEXT NOT NULL
      , is_booked INTEGER DEFAULT 1);
CREATE TABLE invoices (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_number TEXT UNIQUE NOT NULL,
        request_id INTEGER NOT NULL,
        quote_id INTEGER,
        customer_id INTEGER,
        provider_id INTEGER,
        subtotal INTEGER NOT NULL DEFAULT 0,
        materials_total INTEGER NOT NULL DEFAULT 0,
        labor_total INTEGER NOT NULL DEFAULT 0,
        discount INTEGER NOT NULL DEFAULT 0,
        tax INTEGER NOT NULL DEFAULT 0,
        total_amount INTEGER NOT NULL,
        status TEXT DEFAULT 'issued',
        items_json TEXT,
        created_at TEXT NOT NULL
      );
CREATE TABLE payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        invoice_id INTEGER,
        request_id INTEGER NOT NULL,
        customer_id INTEGER,
        amount INTEGER NOT NULL,
        payment_method TEXT DEFAULT 'online',
        transaction_ref TEXT,
        status TEXT DEFAULT 'completed',
        paid_at TEXT,
        created_at TEXT NOT NULL
      , refunded_amount INTEGER DEFAULT 0, updated_at TEXT);
CREATE TABLE provider_settlements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        provider_id INTEGER NOT NULL,
        gross_amount INTEGER NOT NULL,
        commission_rate REAL DEFAULT 0.15,
        commission_amount INTEGER NOT NULL,
        net_payable INTEGER NOT NULL,
        status TEXT DEFAULT 'pending',
        settled_at TEXT,
        created_at TEXT NOT NULL
      , labor_amount INTEGER DEFAULT 0, materials_amount INTEGER DEFAULT 0, platform_fee INTEGER DEFAULT 0, tax_amount INTEGER DEFAULT 0);
CREATE TABLE ratings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER UNIQUE NOT NULL,
        customer_id INTEGER NOT NULL,
        provider_id INTEGER NOT NULL,
        overall_score INTEGER NOT NULL,
        punctuality_score INTEGER DEFAULT 5,
        cleanliness_score INTEGER DEFAULT 5,
        skill_score INTEGER DEFAULT 5,
        comment TEXT,
        status TEXT DEFAULT 'approved',
        created_at TEXT NOT NULL
      );
CREATE TABLE disputes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER NOT NULL,
        opened_by TEXT NOT NULL,
        opened_by_id INTEGER,
        reason TEXT NOT NULL,
        claim_amount INTEGER DEFAULT 0,
        description TEXT NOT NULL,
        evidence_urls_json TEXT,
        status TEXT DEFAULT 'open',
        admin_notes TEXT,
        refund_amount INTEGER DEFAULT 0,
        resolved_at TEXT,
        created_at TEXT NOT NULL
      , internal_notes TEXT, provider_compensation INTEGER DEFAULT 0, customer_compensation INTEGER DEFAULT 0, resolved_by TEXT);
CREATE TABLE support_tickets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER,
        provider_id INTEGER,
        request_id INTEGER,
        dispute_id INTEGER,
        subject TEXT NOT NULL,
        category TEXT DEFAULT 'general',
        priority TEXT DEFAULT 'normal',
        status TEXT DEFAULT 'open',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
CREATE TABLE notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        recipient_type TEXT NOT NULL,
        recipient_id INTEGER,
        event_type TEXT NOT NULL,
        title TEXT NOT NULL,
        message TEXT NOT NULL,
        channel TEXT DEFAULT 'in_app',
        is_read INTEGER DEFAULT 0,
        created_at TEXT NOT NULL
      );
