CREATE TABLE commission_rules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        category_id TEXT DEFAULT 'all',
        tier TEXT DEFAULT 'all',
        rate REAL NOT NULL DEFAULT 0.15,
        min_fee INTEGER DEFAULT 0,
        max_fee INTEGER DEFAULT 0,
        calculation_basis TEXT DEFAULT 'all',
        is_active INTEGER DEFAULT 1,
        created_at TEXT NOT NULL
      , scope TEXT DEFAULT 'global', scope_id TEXT DEFAULT 'all', effective_date TEXT);
INSERT INTO "commission_rules" ("id","category_id","tier","rate","min_fee","max_fee","calculation_basis","is_active","created_at","scope","scope_id","effective_date") VALUES(1,'all','all',0.15,0,0,'all',1,'2026-09-19T10:15:11.390Z','global','all',NULL);
CREATE TABLE financial_ledger (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ledger_tx_id TEXT,
        entry_type TEXT NOT NULL,
        order_id INTEGER NOT NULL,
        payment_id INTEGER,
        invoice_id INTEGER,
        customer_id INTEGER,
        provider_id INTEGER,
        account_type TEXT DEFAULT 'platform',
        direction TEXT DEFAULT 'credit',
        amount INTEGER NOT NULL,
        currency TEXT DEFAULT 'IRT',
        balance_after INTEGER DEFAULT 0,
        status TEXT DEFAULT 'posted',
        reference_type TEXT,
        reference_id TEXT,
        description TEXT,
        created_at TEXT NOT NULL,
        FOREIGN KEY (order_id) REFERENCES requests(id) ON DELETE CASCADE
      );
CREATE TABLE idempotency_keys (
        key TEXT PRIMARY KEY,
        resource_type TEXT NOT NULL,
        resource_id TEXT,
        response_status INTEGER NOT NULL,
        response_body TEXT NOT NULL,
        created_at TEXT NOT NULL
      );
CREATE TABLE provider_notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        provider_id INTEGER NOT NULL,
        type TEXT NOT NULL,
        title TEXT NOT NULL,
        message TEXT NOT NULL,
        data_json TEXT,
        is_read INTEGER DEFAULT 0,
        created_at TEXT NOT NULL,
        FOREIGN KEY (provider_id) REFERENCES providers(id) ON DELETE CASCADE
      );
CREATE TABLE admin_users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        full_name TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'operations_admin',
        permissions TEXT,
        phone TEXT,
        token TEXT UNIQUE,
        is_active INTEGER DEFAULT 1,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
